import{_ as s,l as m,o as t,c as n,v as e,p as o,x as i,d,i as l,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"随机微分方程的含义","description":"","frontmatter":{"title":"随机微分方程的含义","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sde-meaning.md","filePath":"quant/sde-meaning.md","lastUpdated":1789023840000}'),E={name:"quant/sde-meaning.md"};function p(c,a,u,_,B,A){const r=m("Mermaid");return t(),n("div",null,[a[1]||(a[1]=e('<h1 id="随机微分方程的含义" tabindex="-1">随机微分方程的含义 <a class="header-anchor" href="#随机微分方程的含义" aria-label="Permalink to &quot;随机微分方程的含义&quot;">​</a></h1><div class="epigraph"><p>SDE 不是把 $\\mathrm d X=\\mu\\,\\mathrm d t+\\sigma\\,\\mathrm d W$ 当作轨迹上的常微分方程；它是伊藤积分方程的简写。</p><footer>—— 据 Øksendal, Stochastic Differential Equations, 第 6 版, 2003, 第 5 章；Shreve, Stochastic Calculus for Finance II, 2004, 第 4–5 章整理</footer></div><p>上一课<a href="/quant/ito-lemma">伊藤引理</a>给出对已知过程的微分法则。缺口是反过来：若我们<strong>指定</strong>漂移与扩散，要的对象是哪一个过程。把 \\(\\mathrm d W/\\mathrm d t\\) 写成白噪声再当 ODE 来解，路径不可微，式子没有意义。本课只把 SDE 读成积分方程，并留下存在唯一的 Lipschitz 接口，供下一课写出 GBM。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>布朗路径几乎必然不可微，\\(\\dot W\\) 不存在。因此「\\(\\dot X=\\mu(t,X)+\\sigma(t,X)\\dot W\\)」不是本课程的对象。需要一个不依赖路径导数的定义：把 \\(\\mathrm d t\\) 项写成普通积分，把 \\(\\mathrm d W\\) 项写成伊藤积分。缺口是承认这是定义，而不是写法偏好。</p><p>没有存在唯一，后面的定价 PDE、蒙特卡洛离散化都没有「那个」\\(X\\) 可指。本课不把证明写全，只把条件说成后课默认的正则性。</p><h3 id="sde-的解不是「每条路径上的-ode」" tabindex="-1">SDE 的解不是「每条路径上的 ODE」 <a class="header-anchor" href="#sde-的解不是「每条路径上的-ode」" aria-label="Permalink to &quot;SDE 的解不是「每条路径上的 ODE」&quot;">​</a></h3><p>强解是：在给定的 \\(W\\) 上，存在适应过程 \\(X\\)，使积分方程几乎必然成立。弱解只匹配分布，可以换一个更大的空间另造一个布朗。定价算期望时弱解往往够用；对冲要沿给定 \\(W\\) 复制时，需要强解。本课先以强解为默认对象，避免把「解」理解成逐条轨迹上的牛顿迭代。</p><p><span class="marginnote">Euler–Maruyama 是把积分方程按左端点切开，不是把 \\(\\dot W\\) 换成 \\(\\Delta W/\\Delta t\\)。后课蒙特卡洛用的就是这一离散，不是 ODE 求解器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记号 \\(\\mathrm d X_t=\\mu(t,X_t)\\,\\mathrm d t+\\sigma(t,X_t)\\,\\mathrm d W_t\\) 定义为</p> \\[X_t=X_0+\\int_0^t\\mu(s,X_s)\\,\\mathrm d s+\\int_0^t\\sigma(s,X_s)\\,\\mathrm d W_s. \\]<p>\\(\\mu\\) 叫漂移，\\(\\sigma\\) 叫扩散。适应：\\(\\sigma(s,X_s)\\) 在 \\(s\\) 时刻已确定，才能作为伊藤被积过程。若 \\(\\mu,\\sigma\\) 对 \\(x\\) 全局 Lipschitz、线性增长，则强解存在且轨道唯一。线性增长挡住有限时间爆炸；Lipschitz 挡住分叉。金融里常用的 GBM、Vasicek、CIR（在参数允许时）被当作满足或局部满足这些条件的模板。</p><p>解是马尔可夫过程时，Itô 公式里的漂移算子 \\(\\mathcal A\\) 就是无穷小生成元。后课 Feynman–Kac 把这个算子接到 PDE，本课只指出接口：SDE 决定 \\(\\mathcal A\\)，不决定边界条件。</p>',14)),(t(),o(h,null,{default:i(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%5B%22SDE%20%E8%AE%B0%E5%8F%B7%22%5D%20--%3E%20INT%5B%22%E7%A7%AF%E5%88%86%E6%96%B9%E7%A8%8B%22%5D%0A%20%20INT%20--%3E%20STRONG%5B%22%E5%BC%BA%E8%A7%A3%EF%BC%9A%E6%B2%BF%E7%BB%99%E5%AE%9A%20W%22%5D%0A%20%20INT%20--%3E%20LIP%5B%22Lipschitz%20%E5%8A%A0%E7%BA%BF%E6%80%A7%E5%A2%9E%E9%95%BF%22%5D%0A%20%20LIP%20--%3E%20UNIQUE%5B%22%E8%BD%A8%E9%81%93%E5%94%AF%E4%B8%80%22%5D%0A%20%20STRONG%20--%3E%20GBM%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9AGBM%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>伊藤积分的被积过程不能偷看未来的 \\(\\Delta W\\)。这把「策略必须适应信息流」写进方程本身：扩散系数若依赖未发生的增量，积分无定义。漂移积分是有限变差，不贡献二次变差；全部二次变差来自 \\(\\int\\sigma\\,\\mathrm d W\\)。因此后课写 \\([X]_t=\\int\\sigma^2\\)，不必再对 \\(\\mu\\) 操心。</p><p>时间齐次时，从 \\(x\\) 出发的解的分布只依赖 \\(t\\) 与 \\(x\\)，这是定价函数写成 \\(V(t,S)\\) 的理由。非齐次、带随机系数时，状态要扩维；本课不展开，只提醒：SDE 的状态是你写进 \\(\\mu,\\sigma\\) 的那个向量。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Yamada–Watanabe，不讨论弱解的鞅问题，不引入跳 SDE。随机波动率把 \\(\\sigma\\) 本身再写成一个过程，主干定价先用常数或确定性 \\(\\sigma\\)。后课默认：看到 \\(\\mathrm d X=\\mu\\,\\mathrm d t+\\sigma\\,\\mathrm d W\\)，即积分方程；存在唯一时默认 Lipschitz 模板。下一课<a href="/quant/geometric-brownian-motion">几何布朗运动</a>给出金融里最常用的强解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SDE 是伊藤积分方程的简写，不是带白噪声的 ODE。</li><li>强解沿给定 \\(W\\)；Lipschitz 加线性增长给出轨道唯一。</li><li>漂移不进二次变差；扩散系数决定 \\([X]\\)。</li><li>Euler 离散对准积分方程的左端点。</li><li>出处：Øksendal 第 5 章；Shreve SDE II 第 4–5 章。</li></ul>',7))])}const f=s(E,[["render",p]]);export{S as __pageData,f as default};
